import { BaseSchema } from '@adonisjs/lucid/schema'
import type { Knex } from 'knex'

/**
 * The gallery tables move from auto-increment integers to CUIDs (generated by
 * the models). Their rows are dropped: this ran before the gallery held real
 * content. Rolling back recreates the integer layout, empty.
 */
type Ids = 'cuid' | 'integer'

const TABLES = [
  'texture_images',
  'texture_outputs',
  'textures',
  'texture_categories',
  'environments',
]

export default class extends BaseSchema {
  private primary(table: Knex.CreateTableBuilder, ids: Ids) {
    if (ids === 'cuid') table.string('id', 32).primary()
    else table.increments('id').notNullable()
  }

  private foreign(table: Knex.CreateTableBuilder, ids: Ids, column: string) {
    return ids === 'cuid' ? table.string(column, 32) : table.integer(column).unsigned()
  }

  private create(ids: Ids) {
    this.schema.createTable('texture_categories', (table) => {
      this.primary(table, ids)
      table.string('slug').notNullable().unique()
      table.string('name').notNullable()
      table.text('description').nullable()
      table.integer('sort_order').notNullable().defaultTo(0)

      table.timestamp('created_at').notNullable()
      table.timestamp('updated_at').nullable()
    })

    this.schema.createTable('textures', (table) => {
      this.primary(table, ids)
      table.string('slug').notNullable().unique()
      table.string('title').notNullable()
      table.text('description').nullable()
      this.foreign(table, ids, 'category_id')
        .nullable()
        .references('id')
        .inTable('texture_categories')
        .onDelete('SET NULL')
      // Lowercase, comma-joined, so LIKE search works the same on postgres and sqlite
      table.string('tags', 1000).notNullable().defaultTo('')

      table.string('status').notNullable().defaultTo('draft')
      table.timestamp('published_at').nullable()
      table.boolean('featured').notNullable().defaultTo(false)
      table.integer('sort_order').notNullable().defaultTo(0)

      // The .texture file
      table.string('source_key').notNullable()
      table.string('source_name').notNullable()
      table.string('source_sha256', 64).notNullable()
      table.integer('source_bytes').notNullable()

      // Read from the file on upload
      table.string('library_version').notNullable()
      table.string('app_version').nullable()
      table.integer('resolution').notNullable()
      table.integer('node_count').notNullable()
      table.integer('connection_count').notNullable()
      table.text('channels').notNullable()
      table.text('variables').notNullable()
      table.text('presets').notNullable()
      table.string('active_preset').nullable()
      table.text('warnings').notNullable()

      // Outputs rendered in /ops; 0 until the first render
      table.integer('outputs_revision').notNullable().defaultTo(0)
      table.string('outputs_sha256', 64).nullable()

      table.integer('download_count').notNullable().defaultTo(0)

      table.timestamp('created_at').notNullable()
      table.timestamp('updated_at').nullable()

      table.index(['status', 'published_at'])
    })

    this.schema.createTable('texture_outputs', (table) => {
      this.primary(table, ids)
      this.foreign(table, ids, 'texture_id')
        .notNullable()
        .references('id')
        .inTable('textures')
        .onDelete('CASCADE')
      table.integer('revision').notNullable()
      table.string('channel').notNullable()
      table.string('key').notNullable()
      // 512px webp for grids and hovers
      table.string('thumb_key').nullable()
      table.integer('width').notNullable()
      table.integer('height').notNullable()
      table.integer('bit_depth').notNullable()
      table.string('color_type').notNullable()
      table.string('format').notNullable()
      table.integer('bytes').notNullable()
      table.string('render_target_format').nullable()

      table.timestamp('created_at').notNullable()
      table.timestamp('updated_at').nullable()

      table.unique(['texture_id', 'revision', 'channel'])
    })

    this.schema.createTable('texture_images', (table) => {
      this.primary(table, ids)
      this.foreign(table, ids, 'texture_id')
        .notNullable()
        .references('id')
        .inTable('textures')
        .onDelete('CASCADE')
      table.string('key').notNullable()
      table.string('thumb_key').notNullable()
      table.integer('width').notNullable()
      table.integer('height').notNullable()
      table.integer('bytes').notNullable()
      table.string('alt').nullable()
      // "upload" from an admin, "render" captured from the 3D viewer in /ops
      table.string('source').notNullable().defaultTo('upload')
      table.boolean('is_primary').notNullable().defaultTo(false)
      table.integer('sort_order').notNullable().defaultTo(0)

      table.timestamp('created_at').notNullable()
      table.timestamp('updated_at').nullable()
    })

    this.schema.createTable('environments', (table) => {
      this.primary(table, ids)
      table.string('name').notNullable()
      // "hdr" (Radiance) or "exr" (OpenEXR)
      table.string('format').notNullable()
      // An uploaded file in storage ("upload") or an external link ("url")
      table.string('source').notNullable()
      table.string('key').nullable()
      table.string('url', 2000).nullable()
      table.integer('bytes').nullable()
      table.string('thumb_key').nullable()
      table.boolean('is_default').notNullable().defaultTo(false)
      table.integer('sort_order').notNullable().defaultTo(0)

      table.timestamp('created_at').notNullable()
      table.timestamp('updated_at').nullable()
    })
  }

  private drop() {
    for (const table of TABLES) this.schema.dropTableIfExists(table)
  }

  async up() {
    this.drop()
    this.create('cuid')
  }

  async down() {
    this.drop()
    this.create('integer')
  }
}
